.bm { background:var(--card); border:1px solid var(--line); border-radius:12px; padding:14px 16px; animation:pop .25s ease; }
@keyframes pop { from{opacity:0; transform:translateY(6px);} to{opacity:1; transform:none;} }
.bm .title { font-size:15px; font-weight:600; margin:0 0 3px; }
.bm .url { font-size:13px; color:var(--accent); word-break:break-all; }
.bm .desc { font-size:13px; color:var(--muted); margin:6px 0 0; }
.bm .meta { font-size:12px; color:var(--muted); margin-top:8px; }
.flash { background:#e8f0ff; border-color:#c7dbff; }

input.new_string:
.bm { background:var(--card); border:1px solid var(--line); border-radius:12px; padding:14px 16px; animation:pop .25s ease; display:flex; gap:12px; }
@keyframes pop { from{opacity:0; transform:translateY(6px);} to{opacity:1; transform:none;} }
.fav { flex:0 0 34px; width:34px; height:34px; border-radius:8px; display:flex; align-items:center; justify-content:center; color:#fff; font-weight:700; font-size:15px; margin-top:2px; }
.bm .body { flex:1; min-width:0; }
.bm .title a { font-size:15px; font-weight:600; color:var(--ink); text-decoration:none; }
.bm .title a:hover { text-decoration:underline; }
.bm .desc { font-size:13px; color:#4b5563; margin:5px 0 0; }
.bm .url { font-size:11.5px; color:var(--muted); word-break:break-all; margin-top:7px; }
.bm .actions { margin-top:9px; }
.bm .actions button { background:none; border:0; color:var(--accent); font-size:12.5px; cursor:pointer; padding:0; }
.flash { background:#e8f0ff; border-color:#c7dbff; }
.edit { display:flex; flex-direction:column; gap:8px; margin-top:4px; }
.edit input, .edit textarea { padding:8px 10px; border:1px solid var(--line); border-radius:7px; font-size:14px; font-family:inherit; }
.edit textarea { resize:vertical; min-height:52px; }
.edit .row { display:flex; gap:8px; }
.edit .row button { padding:7px 14px; border-radius:7px; font-size:13px; cursor:pointer; border:1px solid var(--line); background:#fff; }
.edit .row button.primary { background:var(--accent); color:#fff; border-color:var(--accent); font-weight:600; }

