// Prototype stand-in for a favicon: a coloured monogram from the site host, so
// the layout is real without depending on external icon fetches during review.
const FAV_COLORS = ["#2f6df6","#e2528b","#12a150","#f59e0b","#8b5cf6","#0891b2","#dc2626"];
function faviconFor(u){
  const host = u.hostname.replace(/^www\./,'');
  let sum = 0; for(const c of host) sum += c.charCodeAt(0);
  return { letter: host.charAt(0).toUpperCase(), color: FAV_COLORS[sum % FAV_COLORS.length] };
}

