input.new_string:
  listEl.innerHTML = '';
  bookmarks.forEach((b, i) => {
    const el = document.createElement('div');
    el.className = 'bm' + (b.flash ? ' flash' : '');
    const fav = document.createElement('div');
    fav.className = 'fav';
    fav.style.background = b.fav.color;
    fav.textContent = b.fav.letter;
    el.appendChild(fav);

    const body = document.createElement('div');
    body.className = 'body';
    el.appendChild(body);

    if(b.editing){
      body.innerHTML =
        `<div class="edit">
           <input class="e-title" type="text" />
           <textarea class="e-desc" placeholder="Description or your own notes"></textarea>
           <div class="row"><button class="primary e-save">Save changes</button><button class="e-cancel">Cancel</button></div>
         </div>`;
      body.querySelector('.e-title').value = b.title;
      body.querySelector('.e-desc').value = b.desc || '';
      body.querySelector('.e-save').addEventListener('click', () => {
        b.title = body.querySelector('.e-title').value.trim() || b.title;
        b.desc = body.querySelector('.e-desc').value.trim();
        b.editing = false; render();
        statusEl.textContent = "Your changes are saved.";
      });
      body.querySelector('.e-cancel').addEventListener('click', () => { b.editing = false; render(); });
    } else {
      const desc = b.desc ? `<p class="desc"></p>` : '';
      body.innerHTML =
        `<p class="title"><a href="${b.url}" target="_blank" rel="noopener"></a></p>` +
        desc +
        `<div class="url"></div>` +
        `<div class="actions"><button class="e-edit">Edit details</button></div>`;
      body.querySelector('.title a').textContent = b.title;
      body.querySelector('.url').textContent = b.url;
      if(b.desc) body.querySelector('.desc').textContent = b.desc;
      body.querySelector('.e-edit').addEventListener('click', () => { b.editing = true; render(); });
    }
    listEl.appendChild(el);
    b.flash = false;
  });
}

