  if(!inView(b)) return false;
  if(activeTags.size){ for(const t of activeTags) if(!b.tags.includes(t)) return false; }
  if(!compiled.ok) return false;
  return compiled.pred(b);
}
function counts(){ return {
  all: bookmarks.filter(b=>!b.archived).length,
  toread: bookmarks.filter(b=>!b.archived && b.readLater).length,
  archived: bookmarks.filter(b=>b.archived).length }; }
