  query=''; document.getElementById('search').value=''; compiled=parseQuery(''); highlightTerms=[]; activeTags.clear();
  view = dup.archived ? 'archived' : 'all';
  dup.flash=true; update();
  const node=[...listEl.children].find(n=>n.dataset.url===dup.url);
  if(node) node.scrollIntoView({behavior:'smooth', block:'center'});
}
function startAdd(){
  const u=normalizeUrl(urlEl.value); if(!u){ statusEl.textContent="That doesn't look like a valid link yet."; return; }
  const dup=bookmarks.find(b=>b.url===u.href);
  if(dup){ urlEl.value=''; slot.innerHTML='';
    statusEl.textContent = dup.archived
      ? "You already saved this link (it's in your Archive) — here it is."
      : "You already saved this link — here it is.";
    revealExisting(dup); return; }
  addBtn.disabled=true; statusEl.textContent="Fetching page details…";
  setTimeout(()=>{ const info=fakeFetchInfo(u); addBtn.disabled=false;
    const base={ url:u.href, fav:faviconFor(u), title:info.title, desc:info.desc, note:'', tags:[], fetched:true };
    const wrap=draftFields(base); slot.innerHTML=''; slot.appendChild(wrap);
    statusEl.textContent="Review and add tags, then confirm.";
    wrap.querySelector('.d-save').addEventListener('click',()=>{ const nb=readDraft(wrap,base); nb.readLater=false; nb.archived=false; nb.flash=true; bookmarks.unshift(nb); urlEl.value=''; slot.innerHTML=''; statusEl.textContent="Saved."; urlEl.focus(); update(); });
    wrap.querySelector('.d-cancel').addEventListener('click',()=>{ slot.innerHTML=''; statusEl.textContent=''; });
    wrap.querySelector('.d-title').focus();
  },550);
}

