function normalizeUrl(raw){ let s=raw.trim(); if(!s) return null; if(!/^https?:\/\//i.test(s)) s="https://"+s; try{return new URL(s);}catch(e){return null;} }
// dedupe key: ignore scheme, lowercase host, drop a single trailing slash on the path
function dupKey(u){ try{ const x=(typeof u==='string')?new URL(u):u;
  const path=x.pathname.replace(/\/$/,''); return x.hostname.replace(/^www\./,'').toLowerCase()+path+x.search; }catch(e){ return String(u); } }

