const SORT_LABELS={newest:'Newest first',recent:'Recently updated',oldest:'Oldest first','title-az':'Title A–Z','title-za':'Title Z–A'};
let defaultSort = (()=>{ try{ return localStorage.getItem('bm_default_sort')||'newest'; }catch(e){ return 'newest'; } })();
let sortBy = defaultSort;

input.new_string:
const sortEl=document.getElementById('sort'), sortNote=document.getElementById('sortnote');
function refreshSortNote(){
  if(sortBy===defaultSort){ sortNote.innerHTML=`Sorted by your default (${SORT_LABELS[defaultSort]}).`; }
  else { sortNote.innerHTML=`Temporary sort — <a id="resetsort">return to default (${SORT_LABELS[defaultSort]})</a>.`;
    sortNote.querySelector('#resetsort').addEventListener('click',()=>{ sortBy=defaultSort; sortEl.value=sortBy; render(); refreshSortNote(); }); }
}
sortEl.value=sortBy;
sortEl.addEventListener('change',e=>{ sortBy=e.target.value; render(); refreshSortNote(); }); // temporary only, not persisted
refreshSortNote();

// settings: explicit default sort
document.getElementById('gear').addEventListener('click',()=>{
  const ov=document.createElement('div'); ov.className='overlay';
  const card=document.createElement('div'); card.className='card'; card.style.maxWidth='420px';
  card.innerHTML=`<div style="font-weight:600;margin-bottom:4px">Settings</div>
    <div class="setrow"><label>Default sort — how the list is ordered when you open the app</label>
      <select id="defsort">${Object.entries(SORT_LABELS).map(([k,l])=>`<option value="${k}">${l}</option>`).join('')}</select></div>
    <div class="hint" style="margin-top:8px">Changing the sort dropdown only affects this session; your default stays until you change it here.</div>
    <div class="row" style="margin-top:14px;display:flex;gap:8px"><button class="btn" id="setsave">Save</button><button class="btn ghost" id="setclose">Close</button></div>`;
  ov.appendChild(card); document.body.appendChild(ov);
  card.querySelector('#defsort').value=defaultSort;
  card.querySelector('#setsave').addEventListener('click',()=>{ defaultSort=card.querySelector('#defsort').value;
    try{ localStorage.setItem('bm_default_sort',defaultSort); }catch(_){}
    sortBy=defaultSort; sortEl.value=sortBy; render(); refreshSortNote(); ov.remove(); statusEl.textContent="Default sort saved."; });
  card.querySelector('#setclose').addEventListener('click',()=>ov.remove());
});

