.bm { background:var(--card); border:1px solid var(--line); border-radius:12px; padding:14px 16px; display:flex; gap:12px; }
.bm.selected { border-color:var(--accent); background:#f6f9ff; }
.selbox { flex:0 0 18px; margin-top:6px; }
.selbox input { width:16px; height:16px; cursor:pointer; }
.bulkbar { position:sticky; top:8px; z-index:6; background:var(--ink); color:#fff; border-radius:10px; padding:10px 14px; display:flex; flex-wrap:wrap; gap:10px; align-items:center; margin-bottom:10px; box-shadow:0 6px 18px rgba(20,25,35,.18); }
.bulkbar .n { font-weight:600; }
.bulkbar button { background:rgba(255,255,255,.14); color:#fff; border:0; border-radius:7px; padding:6px 11px; font-size:12.5px; cursor:pointer; }
.bulkbar button:hover { background:rgba(255,255,255,.26); }
.bulkbar button.danger { background:#7f1d1d; }
.bulkbar input.tagin { border:0; border-radius:7px; padding:6px 9px; font-size:12.5px; width:130px; }
.bulkbar .sep { width:1px; align-self:stretch; background:rgba(255,255,255,.22); margin:0 2px; }
.bulkbar .link { background:none; text-decoration:underline; padding:6px 2px; }

