function renderBulkBar(){
  const bar=document.getElementById('bulkbar');
  const sel=[...selected];
  if(sel.length===0){ bar.className='bulkbar hidden'; bar.innerHTML=''; return; }
  bar.className='bulkbar';
  const shown=bookmarks.filter(matches);
  const allShownSelected = shown.length>0 && shown.every(b=>selected.has(b));
  bar.innerHTML=`<span class="n">${sel.length} selected</span>`+
    `<button class="link" data-a="selall">${allShownSelected?'Deselect':'Select'} all ${shown.length} shown</button>`+
    `<button class="link" data-a="clear">Clear</button>`+
    `<span class="sep"></span>`+
    `<input class="tagin" placeholder="tag name…">`+
    `<button data-a="addtag">Add tag</button>`+
    `<button data-a="rmtag">Remove tag</button>`+
    `<span class="sep"></span>`+
    `<button data-a="read">Mark read later</button>`+
    `<button data-a="unread">Unmark</button>`+
    `<button data-a="arch">Archive</button>`+
    `<button data-a="unarch">Unarchive</button>`+
    `<span class="sep"></span>`+
    `<button class="danger" data-a="del">Delete…</button>`;
  const tagin=bar.querySelector('.tagin');
  const norm=s=>s.trim().toLowerCase();
  bar.querySelectorAll('button[data-a]').forEach(btn=>btn.addEventListener('click',()=>{
    const a=btn.dataset.a; const sel2=[...selected];
    if(a==='selall'){ if(allShownSelected) shown.forEach(b=>selected.delete(b)); else shown.forEach(b=>selected.add(b)); update(); return; }
    if(a==='clear'){ selected.clear(); update(); return; }
    if(a==='addtag'){ const t=norm(tagin.value); if(!t){ statusEl.textContent="Type a tag name to add."; return; }
      let n=0; sel2.forEach(b=>{ if(!b.tags.includes(t)){ b.tags.push(t); b.updatedAt=Date.now(); n++; } });
      statusEl.textContent=`Added “${t}” to ${n} bookmark(s).`; update(); return; }
    if(a==='rmtag'){ const t=norm(tagin.value); if(!t){ statusEl.textContent="Type a tag name to remove."; return; }
      let n=0; sel2.forEach(b=>{ const i=b.tags.indexOf(t); if(i>=0){ b.tags.splice(i,1); b.updatedAt=Date.now(); n++; } });
      statusEl.textContent=`Removed “${t}” from ${n} bookmark(s).`; update(); return; }
    if(a==='read'){ sel2.forEach(b=>b.readLater=true); statusEl.textContent=`Marked ${sel2.length} to read later.`; update(); return; }
    if(a==='unread'){ sel2.forEach(b=>b.readLater=false); statusEl.textContent=`Unmarked ${sel2.length}.`; update(); return; }
    if(a==='arch'){ sel2.forEach(b=>b.archived=true); statusEl.textContent=`Archived ${sel2.length}.`; selected.clear(); update(); return; }
    if(a==='unarch'){ sel2.forEach(b=>b.archived=false); statusEl.textContent=`Unarchived ${sel2.length}.`; selected.clear(); update(); return; }
    if(a==='del'){
      bar.innerHTML=`<span class="n">Delete ${sel2.length} bookmark(s) permanently? This can't be undone.</span>`+
        `<button class="danger" data-y>Delete permanently</button><button class="link" data-n>Keep</button>`;
      bar.querySelector('[data-y]').addEventListener('click',()=>{ sel2.forEach(b=>{ const i=bookmarks.indexOf(b); if(i>=0)bookmarks.splice(i,1); }); statusEl.textContent=`Deleted ${sel2.length} bookmark(s).`; selected.clear(); update(); });
      bar.querySelector('[data-n]').addEventListener('click',renderBulkBar);
      return; }
  }));
}
function update(){ renderViews(); renderFilters(); renderBulkBar(); render(); }

