function currentSig(){ return JSON.stringify({ q:query.trim(), t:[...activeTags].sort() }); }
function collSig(c){ return JSON.stringify({ q:(c.query||'').trim(), t:[...(c.tags||[])].sort() }); }
function persistColls(){ try{ localStorage.setItem('bm_collections', JSON.stringify(collections)); }catch(_){} }
function applyCollection(c){
  query=c.query||''; const se=document.getElementById('search'); if(se) se.value=query;
  compiled=parseQuery(query); highlightTerms=termsFromQuery(query);
  activeTags=new Set(c.tags||[]);
  const en=document.getElementById('searcherr'); if(en) en.textContent = compiled.ok?'':"That search isn't complete yet — check quotes and parentheses.";
  update(); if(typeof refreshSortNote==='function') {}
}
function renderCollections(){
  const box=document.getElementById('collections'); box.innerHTML='';
  const sig=currentSig();
  if(collections.length){ const l=document.createElement('span'); l.className='clbl'; l.textContent='Collections:'; box.appendChild(l); }
  collections.forEach((c,idx)=>{
    const on = collSig(c)===sig;
    const el=document.createElement('span'); el.className='coll'+(on?' on':'');
    el.innerHTML=`${escapeHtml(c.name)} <span class="x" title="Remove collection">×</span>`;
    el.addEventListener('click',e=>{ if(e.target.classList.contains('x')){ collections.splice(idx,1); persistColls(); renderCollections(); statusEl.textContent=`Removed collection “${c.name}”.`; return; }
      applyCollection(c); statusEl.textContent=`Showing collection “${c.name}”.`; });
    box.appendChild(el);
  });
  // save-current control (only when there is something to save and it isn't already an existing collection)
  const hasCriteria = query.trim() || activeTags.size;
  const alreadySaved = collections.some(c=>collSig(c)===sig);
  if(hasCriteria && !alreadySaved){
    const save=document.createElement('button'); save.className='save'; save.textContent='＋ Save current search';
    save.addEventListener('click',()=>{
      const form=document.createElement('form');
      form.innerHTML=`<input placeholder="Name this collection…" maxlength="40"><button type="submit">Save</button>`;
      const inp=form.querySelector('input');
      form.addEventListener('submit',e=>{ e.preventDefault(); const name=inp.value.trim(); if(!name){ inp.focus(); return; }
        collections.push({ name, query:query, tags:[...activeTags] }); persistColls(); renderCollections();
        statusEl.textContent=`Saved collection “${name}”.`; });
      box.replaceChild(form, save); inp.focus();
    });
    box.appendChild(save);
  }
}
function update(){ renderViews(); renderCollections(); renderFilters(); renderBulkBar(); render(); }

