// ---- Block E: local copy / PDF / Internet Archive (SIMULATED in prototype) ----
function isPdf(url){ return /\.pdf(\?|#|$)/i.test(url); }
function fmtDate(ms){ const d=new Date(ms); return d.toLocaleDateString(undefined,{year:'numeric',month:'short',day:'numeric'}); }
function openSimCopy(b){
  const w=window.open('','_blank'); if(!w) return;
  const pdf=isPdf(b.url);
  w.document.write(`<!doctype html><meta charset=utf-8><title>Saved copy — ${escapeHtml(b.title)}</title>`+
    `<body style="font-family:system-ui;max-width:640px;margin:40px auto;padding:0 16px;color:#1c2330">`+
    `<div style="background:#fef3c7;border:1px solid #fde68a;padding:10px 12px;border-radius:8px;font-size:13px">Prototype: this is a simulated locally-stored ${pdf?'PDF':'page copy'} for review, not a real capture.</div>`+
    `<h1 style="font-size:20px">${escapeHtml(b.title)}</h1>`+
    `<p style="color:#6b7280;font-size:13px">Locally stored ${pdf?'PDF':'copy'} · captured ${fmtDate(b.snapshot.at)}<br>Original: ${escapeHtml(b.url)}</p>`+
    `<p>${pdf?'The saved PDF file would open here.':'The saved readable copy of the page would appear here, viewable even if the original goes offline.'}</p></body>`);
  w.document.close();
}
function renderCopies(b, host){
  host.innerHTML='';
  const pdf=isPdf(b.url);
  // local copy / PDF
  const c1=document.createElement('span'); c1.className='copy-item';
  if(b.snapshot && b.snapshot.at){
    c1.innerHTML=`<span class="ok">✓ ${pdf?'PDF stored':'Local copy'} (${fmtDate(b.snapshot.at)})</span> · <button class="linkb view">View</button> · <button class="linkb re">Update</button>`;
    c1.querySelector('.view').addEventListener('click',()=>openSimCopy(b));
    c1.querySelector('.re').addEventListener('click',()=>captureSnapshot(b));
  } else if(b.snapshot && b.snapshot.status==='saving'){
    c1.innerHTML=`<span class="pending">Saving ${pdf?'PDF':'local copy'}…</span>`;
  } else {
    c1.innerHTML=`<button class="linkb save-copy">${pdf?'Save the PDF':'Save a local copy'}</button>`;
    c1.querySelector('.save-copy').addEventListener('click',()=>captureSnapshot(b));
  }
  host.appendChild(c1);
  const sep=document.createElement('span'); sep.className='cp-sep'; sep.textContent='·'; host.appendChild(sep);
  // internet archive
  const c2=document.createElement('span'); c2.className='copy-item';
  if(b.archiveUrl){
    c2.innerHTML=`<span class="ok">✓ Internet Archive</span> · <a class="linkb" href="${b.archiveUrl}" target="_blank" rel="noopener">Open archived</a>`;
  } else if(b.archiveStatus==='saving'){
    c2.innerHTML=`<span class="pending">Creating Internet Archive copy…</span>`;
  } else {
    c2.innerHTML=`<button class="linkb make-arch">Create Internet Archive copy</button>`;
    c2.querySelector('.make-arch').addEventListener('click',()=>makeArchive(b));
  }
  host.appendChild(c2);
}
function captureSnapshot(b){
  b.snapshot={status:'saving'}; update();
  setTimeout(()=>{ b.snapshot={status:'done', at:Date.now(), pdf:isPdf(b.url)}; b.updatedAt=Date.now();
    statusEl.textContent=isPdf(b.url)?"PDF stored locally (simulated).":"Local copy saved (simulated)."; update(); }, 700);
}
function makeArchive(b){
  b.archiveStatus='saving'; update();
  setTimeout(()=>{ b.archiveStatus='done'; b.archiveUrl='https://web.archive.org/web/*/'+encodeURI(b.url);
    statusEl.textContent="Internet Archive copy created (simulated link to archive.org)."; update(); }, 800);
}

