// ---- Block F: import / export standard (Netscape) bookmark HTML ----
function exportBookmarksHtml(){
  const esc=s=>String(s||'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
  let out='<!DOCTYPE NETSCAPE-Bookmark-file-1>\n<META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8">\n<TITLE>Bookmarks</TITLE>\n<H1>Bookmarks</H1>\n<DL><p>\n';
  bookmarks.forEach(b=>{
    const add=Math.floor((b.addedAt||Date.now())/1000), mod=Math.floor((b.updatedAt||b.addedAt||Date.now())/1000);
    const tags=(b.tags||[]).join(',');
    out+=`    <DT><A HREF="${esc(b.url)}" ADD_DATE="${add}" LAST_MODIFIED="${mod}"${tags?` TAGS="${esc(tags)}"`:''}>${esc(b.title)}</A>\n`;
    if(b.desc) out+=`    <DD>${esc(b.desc)}\n`;
  });
  out+='</DL><p>\n';
  const blob=new Blob([out],{type:'text/html'});
  const a=document.createElement('a'); a.href=URL.createObjectURL(blob);
  a.download='bookmarks.html'; document.body.appendChild(a); a.click(); a.remove();
  statusEl.textContent=`Exported ${bookmarks.length} bookmark(s) as a standard bookmarks.html file.`;
}
function importBookmarksHtml(text){
  const doc=new DOMParser().parseFromString(text,'text/html');
  const anchors=[...doc.querySelectorAll('a[href]')];
  let added=0, skipped=0;
  anchors.forEach(a=>{
    const href=a.getAttribute('href'); const u=normalizeUrl(href||''); if(!u) { return; }
    if(bookmarks.some(b=>dupKey(b.url)===dupKey(u))){ skipped++; return; }
    const addAttr=a.getAttribute('add_date'); const modAttr=a.getAttribute('last_modified');
    const tagsAttr=a.getAttribute('tags')||'';
    const addedAt=addAttr?Number(addAttr)*1000:Date.now();
    bookmarks.push({ url:u.href, fav:faviconFor(u), title:(a.textContent||u.hostname).trim(),
      desc:'', note:'', tags:tagsAttr.split(',').map(t=>t.trim().toLowerCase()).filter(Boolean),
      readLater:false, archived:false, addedAt, updatedAt: modAttr?Number(modAttr)*1000:addedAt });
    added++;
  });
  update();
  statusEl.textContent=`Imported ${added} bookmark(s)${skipped?`, skipped ${skipped} already-saved`:''}.`;
}

