const FAV_COLORS=["#2f6df6","#e2528b","#12a150","#f59e0b","#8b5cf6","#0891b2","#dc2626"];
function faviconFor(u){ const host=u.hostname.replace(/^www\./,''); let s=0; for(const c of host)s+=c.charCodeAt(0); return {letter:host.charAt(0).toUpperCase(), color:FAV_COLORS[s%FAV_COLORS.length]}; }
// preview availability + placeholder gradient (simulates og:image "where available")
function previewFor(url){ let host=''; try{ host=new URL(url).hostname.replace(/^www\./,''); }catch(e){ return null; }
  let s=0; for(const c of host)s+=c.charCodeAt(0); if(s%3===0) return null; // ~1/3 have no preview image
  const a=FAV_COLORS[s%FAV_COLORS.length], b=FAV_COLORS[(s*7+3)%FAV_COLORS.length];
  return `linear-gradient(135deg, ${a}, ${b})`; }

