:root { --bg:#f5f6f8; --card:#fff; --line:#e2e5ea; --ink:#1c2330; --muted:#6b7280; --accent:#2f6df6; --chip:#eef2f8; }
* { box-sizing:border-box; }
body { margin:0; font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif; background:var(--bg); color:var(--ink); }
header { background:var(--card); border-bottom:1px solid var(--line); padding:16px 24px; display:flex; align-items:center; justify-content:space-between; }
header h1 { margin:0; font-size:18px; }
main { max-width:840px; margin:0 auto; padding:20px 16px 64px; }
.btn { padding:10px 16px; border:0; border-radius:8px; background:var(--accent); color:#fff; font-size:14px; font-weight:600; cursor:pointer; }
.btn.ghost { background:#fff; color:var(--ink); border:1px solid var(--line); font-weight:500; }
.btn:disabled { opacity:.5; cursor:default; }
.card { background:var(--card); border:1px solid var(--line); border-radius:12px; padding:16px; }
.status { min-height:20px; margin:8px 2px 0; font-size:13px; color:var(--muted); }
.addrow { display:flex; gap:8px; }
.addrow input { flex:1; padding:10px 12px; border:1px solid var(--line); border-radius:8px; font-size:15px; }
.draft { display:flex; flex-direction:column; gap:10px; margin-top:12px; }
.draft label { font-size:12px; color:var(--muted); }
.draft input, .draft textarea { width:100%; padding:9px 11px; border:1px solid var(--line); border-radius:8px; font-size:14px; font-family:inherit; }
.draft textarea { resize:vertical; min-height:56px; }
.hint { font-size:11.5px; color:var(--muted); margin-top:-4px; }
.previewbox { border:1px solid var(--line); border-radius:8px; padding:8px 10px; background:#fafafa; min-height:20px; font-size:13px; }
.row { display:flex; gap:8px; }
.fetchline { font-size:12.5px; color:#16794b; }
.fetchwarn { font-size:12.5px; color:#92400e; background:#fef3c7; border:1px solid #fde68a; border-radius:8px; padding:8px 10px; }
.tagslot { position:relative; }
.taginput { display:flex; flex-wrap:wrap; gap:6px; align-items:center; border:1px solid var(--line); border-radius:8px; padding:6px 8px; }
.taginput input { border:0; outline:0; flex:1; min-width:120px; padding:4px; font-size:14px; }
.tag { background:var(--chip); border-radius:999px; padding:3px 10px; font-size:12.5px; color:#38445c; display:inline-flex; align-items:center; gap:6px; }
.tag .x { cursor:pointer; color:var(--muted); font-weight:700; }
.tag.click { cursor:pointer; } .tag.click:hover{ background:#e2e9f5; }
.tag.on { background:var(--accent); color:#fff; }
.suggest { position:absolute; left:0; right:0; top:100%; margin-top:4px; background:#fff; border:1px solid var(--line); border-radius:8px; box-shadow:0 6px 20px rgba(20,25,35,.12); z-index:5; overflow:hidden; }
.suggest div { padding:8px 11px; font-size:13.5px; cursor:pointer; }
.suggest div:hover, .suggest div.active { background:var(--chip); }
.suggest .new { color:var(--muted); }
.views { display:flex; gap:6px; margin-top:16px; }
.views button { border:1px solid var(--line); background:#fff; color:#42506a; padding:7px 14px; border-radius:999px; font-size:13px; cursor:pointer; }
.views button.on { background:var(--ink); color:#fff; border-color:var(--ink); }
.collections { display:flex; flex-wrap:wrap; gap:6px; align-items:center; margin-top:10px; }
.collections .clbl { font-size:12px; color:var(--muted); margin-right:2px; }
.collections .coll { background:#eef4ff; color:#1f3d7a; border:1px solid #d3e0fb; border-radius:999px; padding:5px 8px 5px 12px; font-size:12.5px; cursor:pointer; display:inline-flex; align-items:center; gap:8px; }
.collections .coll.on { background:var(--accent); color:#fff; border-color:var(--accent); }
.collections .coll .x { cursor:pointer; opacity:.7; font-weight:700; }
.collections .save { background:#fff; border:1px dashed var(--line); border-radius:999px; padding:5px 12px; font-size:12.5px; cursor:pointer; color:#42506a; }
.collections form { display:inline-flex; gap:6px; align-items:center; }
.collections form input { padding:5px 9px; border:1px solid var(--line); border-radius:999px; font-size:12.5px; }
.collections form button { padding:5px 11px; border:0; border-radius:999px; font-size:12.5px; cursor:pointer; background:var(--accent); color:#fff; }
.searchbar { display:flex; gap:8px; align-items:center; margin:12px 0 4px; }
.searchbar input { flex:1; padding:10px 12px; border:1px solid var(--line); border-radius:8px; font-size:15px; }
.searchbar select { padding:10px 12px; border:1px solid var(--line); border-radius:8px; font-size:14px; background:#fff; }
.searcherr { font-size:12.5px; color:#b91c1c; min-height:16px; margin:2px; }
.sortnote { font-size:12px; color:var(--muted); min-height:16px; margin:0 2px 4px; }
.sortnote a { color:var(--accent); cursor:pointer; }
.filters { display:flex; flex-wrap:wrap; gap:6px; align-items:center; margin-bottom:6px; }
.filters .lbl { font-size:12px; color:var(--muted); margin-right:2px; }
.resultcount { font-size:12.5px; color:var(--muted); margin:2px 2px 10px; }
.bulkbar { position:sticky; top:8px; z-index:6; background:var(--ink); color:#fff; border-radius:10px; padding:10px 14px; display:flex; flex-wrap:wrap; gap:10px; align-items:center; margin-bottom:10px; box-shadow:0 6px 18px rgba(20,25,35,.18); }
.bulkbar .n { font-weight:600; }
.bulkbar button { background:rgba(255,255,255,.14); color:#fff; border:0; border-radius:7px; padding:6px 11px; font-size:12.5px; cursor:pointer; }
.bulkbar button:hover { background:rgba(255,255,255,.26); }
.bulkbar button.danger { background:#7f1d1d; }
.bulkbar input.tagin { border:0; border-radius:7px; padding:6px 9px; font-size:12.5px; width:130px; }
.bulkbar .sep { width:1px; align-self:stretch; background:rgba(255,255,255,.22); margin:0 2px; }
.bulkbar .link { background:none; text-decoration:underline; padding:6px 2px; }
.list { display:flex; flex-direction:column; gap:10px; }
.empty { text-align:center; color:var(--muted); padding:44px 12px; border:1px dashed var(--line); border-radius:12px; }
.empty strong{ display:block; color:var(--ink); margin-bottom:5px; }
.bm { background:var(--card); border:1px solid var(--line); border-radius:12px; padding:14px 16px; display:flex; gap:12px; }
.bm.selected { border-color:var(--accent); background:#f6f9ff; }
.bm.flash { border-color:#c7dbff; background:#f4f8ff; }
.selbox { flex:0 0 18px; margin-top:6px; }
.selbox input { width:16px; height:16px; cursor:pointer; }
.fav { flex:0 0 34px; width:34px; height:34px; border-radius:8px; display:flex; align-items:center; justify-content:center; color:#fff; font-weight:700; font-size:15px; margin-top:2px; overflow:hidden; }
.fav-real { width:22px; height:22px; }
.body { flex:1; min-width:0; }
.title a { font-size:15px; font-weight:600; color:var(--ink); text-decoration:none; }
.title a:hover { text-decoration:underline; }
.desc { font-size:13px; color:#4b5563; margin:5px 0 0; }
.note { font-size:13px; color:#374151; margin:8px 0 0; background:#fafafa; border:1px solid var(--line); border-radius:7px; padding:8px 10px; }
.note :first-child{margin-top:0;} .note :last-child{margin-bottom:0;} .note ul{margin:4px 0;padding-left:18px;} .note a{color:var(--accent);}
.note-label{ font-size:11px; text-transform:uppercase; letter-spacing:.04em; color:var(--muted); margin-bottom:3px; }
.tagrow { margin-top:9px; display:flex; flex-wrap:wrap; gap:6px; }
.copies { margin-top:9px; font-size:12px; color:var(--muted); display:flex; flex-wrap:wrap; gap:6px; align-items:center; }
.copies .cp-sep { color:var(--line); }
.copies .ok { color:#16794b; } .copies .pending { color:#92400e; } .copies .failed { color:#b91c1c; } .copies .warn { color:#92400e; }
.copies .linkb { background:none; border:0; color:var(--accent); font-size:12px; cursor:pointer; padding:0; text-decoration:none; }
.copies .linkb:hover { text-decoration:underline; }
.url { font-size:11.5px; color:var(--muted); word-break:break-all; margin-top:8px; }
.actions { margin-top:9px; display:flex; gap:14px; align-items:center; flex-wrap:wrap; }
.actions button { background:none; border:0; color:var(--accent); font-size:12.5px; cursor:pointer; padding:0; }
.actions .del { margin-left:auto; color:var(--muted); }
.actions .del:hover { color:#b91c1c; text-decoration:underline; }
.actions .confirm-yes { color:#b91c1c; font-weight:600; }
.actions .confirm { font-size:12.5px; color:#92400e; }
.preview { flex:0 0 96px; width:96px; height:62px; border-radius:8px; margin-top:2px; position:relative; overflow:hidden; background-size:cover; background-position:center; }
.preview span { position:absolute; bottom:3px; right:4px; font-size:9px; color:rgba(255,255,255,.9); text-transform:uppercase; letter-spacing:.05em; background:rgba(0,0,0,.28); padding:1px 4px; border-radius:4px; }
mark { background:#fff3ba; padding:0 1px; border-radius:2px; }
.hidden{ display:none; }
.overlay { position:fixed; inset:0; background:rgba(20,25,35,.45); display:flex; align-items:center; justify-content:center; padding:16px; z-index:20; }
.overlay .card { width:100%; max-width:460px; }
.setrow { display:flex; flex-direction:column; gap:6px; margin-top:12px; }
.setrow select { padding:9px 11px; border:1px solid var(--line); border-radius:8px; font-size:14px; }
.pager { display:flex; gap:10px; align-items:center; justify-content:center; margin-top:16px; font-size:13px; color:var(--muted); }
.pager button { border:1px solid var(--line); background:#fff; border-radius:8px; padding:6px 12px; font-size:13px; cursor:pointer; }
.pager button:disabled { opacity:.4; cursor:default; }
